import { randomUUID } from "node:crypto";
import { stat } from "node:fs/promises";
import { join, resolve } from "node:path";
import {
  MAX_REQUEST_DOCUMENT_COUNT,
  MAX_REQUEST_DOCUMENT_SIZE,
  MAX_REQUEST_DOCUMENT_TOTAL_SIZE,
} from "@/lib/request-document-constants";

const DOCUMENT_TYPES: Record<string, { mimeType: string; allowedMimeTypes: string[] }> = {
  ".pdf": { mimeType: "application/pdf", allowedMimeTypes: ["application/pdf"] },
  ".doc": { mimeType: "application/msword", allowedMimeTypes: ["application/msword"] },
  ".docx": {
    mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    allowedMimeTypes: ["application/vnd.openxmlformats-officedocument.wordprocessingml.document"],
  },
  ".jpg": { mimeType: "image/jpeg", allowedMimeTypes: ["image/jpeg"] },
  ".jpeg": { mimeType: "image/jpeg", allowedMimeTypes: ["image/jpeg"] },
  ".png": { mimeType: "image/png", allowedMimeTypes: ["image/png"] },
};

export class RequestDocumentValidationError extends Error {}

export type PreparedRequestDocument = {
  documentId: string;
  fileName: string;
  contents: Buffer;
};

export function getRequestDocumentMimeType(fileName: string): string | null {
  const extension = fileName.slice(fileName.lastIndexOf(".")).toLowerCase();
  return DOCUMENT_TYPES[extension]?.mimeType || null;
}

export async function prepareRequestDocuments(files: File[]): Promise<PreparedRequestDocument[]> {
  if (files.length > MAX_REQUEST_DOCUMENT_COUNT) {
    throw new RequestDocumentValidationError(`Bạn chỉ có thể tải lên tối đa ${MAX_REQUEST_DOCUMENT_COUNT} tài liệu.`);
  }

  const totalSize = files.reduce((total, file) => total + file.size, 0);
  if (totalSize > MAX_REQUEST_DOCUMENT_TOTAL_SIZE) {
    throw new RequestDocumentValidationError("Tổng dung lượng tài liệu vượt quá 50MB.");
  }

  const prepared: PreparedRequestDocument[] = [];
  for (const file of files) {
    const fileName = file.name.replace(/\\/g, "/").split("/").pop()?.replace(/[\u0000-\u001f\u007f]/g, "").trim();
    const extension = fileName ? fileName.slice(fileName.lastIndexOf(".")).toLowerCase() : "";
    const type = DOCUMENT_TYPES[extension];

    if (!fileName || fileName.length > 200 || !type) {
      throw new RequestDocumentValidationError("Chỉ chấp nhận file PDF, DOC, DOCX, JPG hoặc PNG (tên file tối đa 200 ký tự).");
    }
    if (file.size <= 0 || file.size > MAX_REQUEST_DOCUMENT_SIZE) {
      throw new RequestDocumentValidationError(`File "${fileName}" phải có dung lượng từ 1 byte đến 10MB.`);
    }
    if (file.type && file.type !== "application/octet-stream" && !type.allowedMimeTypes.includes(file.type)) {
      throw new RequestDocumentValidationError(`Định dạng file "${fileName}" không khớp với phần mở rộng.`);
    }

    const contents = Buffer.from(await file.arrayBuffer());
    const hasValidSignature = extension === ".pdf"
      ? contents.subarray(0, 5).toString("ascii") === "%PDF-"
      : extension === ".jpg" || extension === ".jpeg"
        ? contents.length >= 3 && contents[0] === 0xff && contents[1] === 0xd8 && contents[2] === 0xff
        : extension === ".png"
          ? contents.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))
          : extension === ".doc"
            ? contents.subarray(0, 8).equals(Buffer.from([0xd0, 0xcf, 0x11, 0xe0, 0xa1, 0xb1, 0x1a, 0xe1]))
            : contents[0] === 0x50 && contents[1] === 0x4b && contents.includes(Buffer.from("[Content_Types].xml"));

    if (!hasValidSignature) {
      throw new RequestDocumentValidationError(`Nội dung file "${fileName}" không đúng định dạng.`);
    }

    prepared.push({
      documentId: randomUUID(),
      fileName,
      contents,
    });
  }

  return prepared;
}

export function getRequestDocumentPath(requestId: string, documentId: string): string {
  if (!/^[A-Za-z0-9_-]+$/.test(requestId) || !/^[A-Za-z0-9-]+$/.test(documentId)) {
    throw new Error("Invalid document storage identifier.");
  }

  const storageRoot = process.env.EQUIDELI_UPLOAD_DIR
    ? resolve(/* turbopackIgnore: true */ process.env.EQUIDELI_UPLOAD_DIR)
    : join(process.cwd(), "storage", "uploads");
  return join(storageRoot, "request-documents", requestId, documentId);
}

export async function getStoredRequestDocumentSize(requestId: string, documentId: string): Promise<number | null> {
  try {
    return (await stat(getRequestDocumentPath(requestId, documentId))).size;
  } catch (error) {
    if (error && typeof error === "object" && "code" in error && error.code === "ENOENT") return null;
    throw error;
  }
}
